import{c as e,Q as l,j as n,m as a}from"./chunks/framework.rWdQudnF.js";const x=JSON.parse('{"title":"架构师-备考 综合知识-系统基础-计算机组成-RAID技术","description":"","frontmatter":{"title":"架构师-备考 综合知识-系统基础-计算机组成-RAID技术"},"headers":[],"relativePath":"综合知识/系统基础/计算机组成/RAID技术.md","filePath":"综合知识/系统基础/计算机组成/RAID技术.md","lastUpdated":null}'),r={name:"综合知识/系统基础/计算机组成/RAID技术.md"};function d(s,t,i,o,g,c){return l(),n("div",null,[...t[0]||(t[0]=[a('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[x] RAID 0/1/5/6/10 特性与容量计算</li><li>[x] RAID 核心目的</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="raid-级别速查" tabindex="-1">RAID 级别速查 <a class="header-anchor" href="#raid-级别速查" aria-label="Permalink to &quot;RAID 级别速查&quot;">​</a></h3><blockquote><p>🎯 一句话结论：<strong>RAID0 无冗余性能最高，RAID1 全镜像最安全，RAID5 分布式奇偶校验（允许坏1块），RAID6 双奇偶校验（允许坏2块），RAID10 先镜像再条带</strong>。</p></blockquote><table tabindex="0"><thead><tr><th style="text-align:left;">级别</th><th style="text-align:center;">冗余</th><th style="text-align:center;">最少盘数</th><th style="text-align:left;">有效容量</th><th style="text-align:center;">允许坏盘</th><th style="text-align:center;">读性能</th><th style="text-align:center;">写性能</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>RAID0</strong></td><td style="text-align:center;">无</td><td style="text-align:center;">2</td><td style="text-align:left;">n×min</td><td style="text-align:center;">0</td><td style="text-align:center;">高</td><td style="text-align:center;">高</td></tr><tr><td style="text-align:left;"><strong>RAID1</strong></td><td style="text-align:center;">镜像</td><td style="text-align:center;">2</td><td style="text-align:left;">1×min</td><td style="text-align:center;">n-1</td><td style="text-align:center;">中</td><td style="text-align:center;">中</td></tr><tr><td style="text-align:left;"><strong>RAID5</strong></td><td style="text-align:center;">1块校验</td><td style="text-align:center;">3</td><td style="text-align:left;">(n-1)×min</td><td style="text-align:center;"><strong>1</strong></td><td style="text-align:center;">高</td><td style="text-align:center;">中</td></tr><tr><td style="text-align:left;"><strong>RAID6</strong></td><td style="text-align:center;">2块校验</td><td style="text-align:center;">4</td><td style="text-align:left;">(n-2)×min</td><td style="text-align:center;"><strong>2</strong></td><td style="text-align:center;">高</td><td style="text-align:center;">低</td></tr><tr><td style="text-align:left;"><strong>RAID10</strong></td><td style="text-align:center;">镜像+条带</td><td style="text-align:center;">4</td><td style="text-align:left;">(n/2)×min</td><td style="text-align:center;">每组最多1</td><td style="text-align:center;">高</td><td style="text-align:center;">中</td></tr></tbody></table><h3 id="容量计算公式" tabindex="-1">容量计算公式 <a class="header-anchor" href="#容量计算公式" aria-label="Permalink to &quot;容量计算公式&quot;">​</a></h3><blockquote><p>🎯 一句话结论：<strong>RAID 有效容量 = (盘数 - 校验盘数) × 最小盘容量</strong>，校验盘数 RAID5=1, RAID6=2, RAID0=0。</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>有效容量 = (N - P) × min(所有盘容量)</span></span></code></pre></div><ul><li>N = 磁盘总数</li><li>P = 校验盘数量（RAID0=0, RAID5=1, RAID6=2）</li><li>若各盘容量不同，取<strong>最小值</strong></li></ul><p><strong>示例</strong>：4 块 80T 硬盘组 RAID6，有效容量 = (4-2)×80 = <strong>160T</strong>。</p><h3 id="raid-目标" tabindex="-1">RAID 目标 <a class="header-anchor" href="#raid-目标" aria-label="Permalink to &quot;RAID 目标&quot;">​</a></h3><blockquote><p>🎯 一句话结论：RAID 的核心目的是<strong>兼顾数据安全性与磁盘 I/O 性能</strong>，而非单纯扩大容量或降低成本。</p></blockquote><ul><li>RAID 通过<strong>冗余</strong>提升数据安全性（镜像/奇偶校验）</li><li>RAID 通过**条带化（striping）**将数据分散到多盘，并行读写提升 I/O 性能</li></ul><h3 id="⚠️-常见坑" tabindex="-1">⚠️ 常见坑 <a class="header-anchor" href="#⚠️-常见坑" aria-label="Permalink to &quot;⚠️ 常见坑&quot;">​</a></h3><table tabindex="0"><thead><tr><th>易错点</th><th>正解</th></tr></thead><tbody><tr><td>RAID0 性能高是因为条带化 I/O 并行，<strong>但无任何冗余保护</strong></td><td>不要误以为 RAID0 有数据保护</td></tr><tr><td>RAID5 只允许坏 <strong>1 块</strong>盘，RAID6 允许坏 <strong>2 块</strong></td><td>不要记反</td></tr><tr><td>容量计算取<strong>最小盘容量</strong>，各盘不同时不能用平均值</td><td>实际场景中各盘容量通常相同</td></tr></tbody></table>',16)])])}const y=e(r,[["render",d]]);export{x as __pageData,y as default};
